insert into public.rerasa_instruments(id,content) values ('gandrang','{"id":"gandrang","name":"GANDRANG","category":"membranofon","region":"makassar gowa","technique":"ditepuk","keywords":"gandrang gandrang pamancak","description":"Instrumen tabuh dalam tradisi musik Makassar. Telusuri hubungan selaput, badan resonansi, dan irama dalam konteks pertunjukan.","subtitle":"Membranofon · Tabuh Ritual & Pesta Adat","image":"assets/gandrang.jpg","audio":null,"descriptionEn":"A drum in Makassar musical traditions. Explore how membranes, a hollow body and the player’s touch shape rhythm.","narrative":"Mulailah dengan memperhatikan badan Gandrang dan permukaan tabuhnya. Dalam keluarga membranofon, selaput yang dibentangkan menjadi sumber getaran utama. Rongga badan membantu membentuk resonansi, sementara sentuhan pemain memberi tekanan, jeda, dan aksen. Di titik ini, kita mengajak pengunjung membaca irama sebagai rangkaian keputusan, bukan sekadar deretan pukulan.\n\nCatatan BPNB Sulawesi Selatan menempatkan Gandrang dalam kehidupan musik Makassar sejak masa Kerajaan Gowa, sebelum kemerdekaan Indonesia. Dalam konteks tari Pakarena, permainan Gandrang berhubungan dengan gerak penari dan kemampuan penabuh. Bayangkan percakapan antara tubuh yang menari dan tangan yang memainkan: keduanya berbagi ruang pertunjukan, tetapi masing-masing mempunyai cara menyampaikan rasa.\n\nPutar model untuk melihat hubungan permukaan dan badan. Geser kontrol urai bagian untuk mengamati skema selaput, pengikat, dan rongga. Setelah itu, bandingkan dengan keluarga drum di tempat lain. Pertanyaan perjalananmu: bagaimana irama yang sama berubah ketika tekanan tangan, bahan, atau ruang pertunjukannya berubah?","narrativeEn":"A drum in Makassar musical traditions. Explore how membranes, a hollow body and the player’s touch shape rhythm.","development":"Kronologi perkembangan bentuk belum terverifikasi.","developmentEn":"A verified chronology of changes to the form is not yet available.","video":"assets/videos/gandrang.webm","videoKind":"schematic","modelType":"gandrang","modelUrl":"","diagram":"assets/exploded/gandrang.svg","diagramEn":"assets/exploded/gandrang-en.svg","gallery":[],"parts":[{"title":"Selaput atas","description":"Permukaan yang bergetar saat ditabuh.","titleEn":"Upper membrane","descriptionEn":"The surface vibrates when struck.","position":null},{"title":"Badan berongga","description":"Ruang yang membantu membentuk resonansi.","titleEn":"Hollow body","descriptionEn":"The cavity helps shape resonance.","position":null},{"title":"Pengikat","description":"Menahan dan mengatur tegangan selaput dalam skema.","titleEn":"Tension cords","descriptionEn":"Hold the membranes and regulate their tension in this model.","position":null},{"title":"Selaput bawah","description":"Permukaan kedua pada model konseptual.","titleEn":"Lower membrane","descriptionEn":"A second vibrating surface in this conceptual model.","position":null}],"sources":[{"title":"BPNB Sulawesi Selatan — Gandrang","url":"https://kebudayaan.kemdikbud.go.id/bpnbsulsel/gandrang-alat-musik-tradisional-makassar/"},{"title":"Smithsonian — keluarga instrumen berdawai","url":"https://festival.si.edu/articles/1975/the-world-family-of-stringed-instruments"}],"published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('kacaping','{"id":"kacaping","name":"KACAPING","category":"kordofon","region":"bugis makassar","technique":"dipetik","keywords":"kacaping kecapi perahu","description":"Instrumen petik dalam kebudayaan Mandar, Bugis, dan Makassar. Petikan dawai dan syair membuka ruang untuk cerita.","subtitle":"Kordofon · Petik Dua Dawai","image":"assets/kacaping.jpg","audio":null,"descriptionEn":"A plucked string instrument in Mandar, Bugis and Makassar cultures. Strings and poetry open a space for storytelling.","narrative":"Di hadapan Kacaping, perhatian berpindah dari pukulan menuju petikan. Dawai yang ditarik lalu dilepaskan bergetar, dan getaran itu diteruskan ke badan instrumen. Perhatikan jalur pendek antara ujung jari, dawai, dan ruang resonansi. Pada model konseptual ini, bentuk memanjang digunakan untuk membantu melihat hubungan antarbagiannya, bukan untuk menggantikan pengukuran artefak.\n\nBuku Profil Anugerah Budaya 2017 mencatat Kacaping dalam kebudayaan Mandar, Bugis, dan Makassar. Petikan dan syair menjadi bagian penting dari pengalaman mendengarnya. Pengunjung diajak membayangkan bagaimana seorang pemain dapat menanggapi suasana pendengar: sebuah alat musik hadir bersama orang, bahasa, dan situasi yang memberi arti pada bunyinya.\n\nBandingkan Kacaping dengan lute dua dawai di Filipina. Kita membandingkan prinsip dawai dan resonator, tanpa menyimpulkan bahwa satu instrumen merupakan asal langsung instrumen lainnya. Cobalah mengurai model, kemudian susun kembali. Pertanyaan perjalananmu: bagian mana yang paling membantu dawai terdengar, dan bagaimana petikan membuka ruang untuk sebuah cerita?","narrativeEn":"A plucked string instrument in Mandar, Bugis and Makassar cultures. Strings and poetry open a space for storytelling.","development":"Kronologi perkembangan bentuk belum terverifikasi.","developmentEn":"A verified chronology of changes to the form is not yet available.","video":"assets/videos/kacaping.webm","videoKind":"schematic","modelType":"kacaping","modelUrl":"","diagram":"assets/exploded/kacaping.svg","diagramEn":"assets/exploded/kacaping-en.svg","gallery":[],"parts":[{"title":"Dawai","description":"Sumber getaran ketika dipetik.","titleEn":"Strings","descriptionEn":"The source of vibration when plucked.","position":null},{"title":"Jembatan dawai","description":"Meneruskan getaran ke badan dalam skema.","titleEn":"Bridge","descriptionEn":"Transfers string vibration to the body.","position":null},{"title":"Papan permukaan","description":"Permukaan resonator konseptual.","titleEn":"Soundboard","descriptionEn":"The surface of the conceptual resonator.","position":null},{"title":"Badan kayu","description":"Rongga untuk memperjelas hubungan bentuk dan bunyi.","titleEn":"Wooden body","descriptionEn":"A cavity that illustrates the relationship between shape and sound.","position":null}],"sources":[{"title":"Kemendikbud — Profil Anugerah Budaya 2017","url":"https://repositori.kemendikdasmen.go.id/4991/1/Buku_Profil_Anugerah_Budaya_2017.pdf"},{"title":"NCCA Filipina — Philippine Music Instruments","url":"https://ncca.gov.ph/about-ncca-3/subcommissions/subcommission-on-the-arts-sca/music/philippine-music-instruments/"}],"published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('pui-pui','{"id":"pui-pui","name":"PUI-PUI","category":"aerofon","region":"makassar gowa sulawesi selatan","technique":"ditiup","keywords":"pui-pui puipui terompet selompret","description":"Instrumen tiup pada metadata prototipe Makassar–Gowa. Telusuri hubungan napas, saluran udara, dan karakter bunyi.","subtitle":"Aerofon · Tiup Lidah Ganda (Double Reed)","image":"assets/pui-pui.jpg","audio":null,"descriptionEn":"A wind instrument associated with Makassar–Gowa in the prototype metadata. Follow breath through the mouthpiece, air channel and bell.","narrative":"Jalur aerofon dimulai dengan napas. Pada Pui-pui, pengunjung diajak membayangkan udara memasuki bagian peniup, bergerak melewati badan, lalu keluar melalui ujung instrumen. Visualisasi ini menyederhanakan bagian-bagian tersebut agar hubungan antara napas, saluran, dan keluaran bunyi dapat dipahami. Detail bentuk lidah dan ukurannya masih memerlukan dokumentasi langsung.\n\nDalam rancangan awal pameran, Pui-pui ditempatkan bersama konteks pertunjukan Gandrang di wilayah Makassar dan Gowa. Narasi prototipe ini mengajak pengunjung membayangkan perbedaan peran keduanya: satu mengolah irama lewat permukaan tabuh, sementara yang lain membawa garis bunyi melalui aliran udara. Keterangan konteks lokal ini mengikuti metadata prototipe dan perlu dikonfirmasi bersama pemain atau kurator.\n\nBuka perbandingan untuk melihat oboe sebagai contoh instrumen lidah ganda dari konteks lain. Kesamaan mekanisme tidak membuat cara memainkan, repertoar, dan makna budayanya sama. Setelah melihat bagian terurai, tanyakan: bagaimana panjang saluran, bukaan, dan napas pemain dapat membantu membentuk pengalaman mendengar?","narrativeEn":"A wind instrument associated with Makassar–Gowa in the prototype metadata. Follow breath through the mouthpiece, air channel and bell.","development":"Kronologi perkembangan bentuk belum terverifikasi.","developmentEn":"A verified chronology of changes to the form is not yet available.","video":"assets/videos/pui-pui.webm","videoKind":"schematic","modelType":"pui-pui","modelUrl":"","diagram":"assets/exploded/pui-pui.svg","diagramEn":"assets/exploded/pui-pui-en.svg","gallery":[],"parts":[{"title":"Bagian peniup","description":"Tempat masuk napas; bentuk lidah disederhanakan.","titleEn":"Mouthpiece","descriptionEn":"Air enters here; the reed shape is simplified.","position":null},{"title":"Badan saluran","description":"Ruang aliran udara pada model.","titleEn":"Bore","descriptionEn":"The air passage within the model.","position":null},{"title":"Lubang nada","description":"Bukaan yang ditampilkan secara konseptual.","titleEn":"Finger holes","descriptionEn":"Conceptual openings used to explore pitch.","position":null},{"title":"Corong ujung","description":"Bagian keluaran pada model prototipe.","titleEn":"Bell","descriptionEn":"The outlet of the prototype model.","position":null}],"sources":[{"title":"Smithsonian — keluarga instrumen berdawai","url":"https://festival.si.edu/articles/1975/the-world-family-of-stringed-instruments"},{"title":"The Met — Watteau, Music and Theater, katalog oboe","url":"https://resources.metmuseum.org/resources/metpublications/pdf/Watteau_Music_and_Theater.pdf"}],"published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('gesok-gesok','{"id":"gesok-gesok","name":"GESOK-GESOK","category":"kordofon","region":"makassar toraja","technique":"digesek","keywords":"gesok-gesok rebab keso keso","description":"Instrumen gesek yang berkaitan dengan Sinrilik Pakesok-kesok. Gerak busur mempertemukan getaran dawai dengan penuturan cerita.","subtitle":"Kordofon · Gesek Tradisional (Rebab Sulsel)","image":"assets/gesok-gesok.jpg","audio":null,"descriptionEn":"A bowed string instrument associated with Sinrilik Pakesok-kesok storytelling. Explore the relationship between bow, strings and resonator.","narrative":"Gesok-gesok memberi pengalaman berbeda di jalur kordofon. Jika petikan menghasilkan getaran setelah dawai dilepaskan, gesekan dapat mempertahankan getaran selama busur bergerak. Perhatikan posisi dawai, badan resonator, dan busurnya. Ketiganya membentuk hubungan gerak yang dapat dieksplorasi melalui model sederhana pada layar.\n\nDokumentasi Warisan Budaya Takbenda 2013 membahas Sinrilik Pakesok-kesok sebagai penuturan yang dilagukan dengan iringan kesok-kesok. Di ruang pameran, hubungan ini menjadi pintu masuk untuk membayangkan bunyi bersama kisah. Dengarkan dengan perhatian pada hubungan antara suara penutur, jeda, dan bunyi pengiring; rekaman pemain diperlukan untuk pengalaman autentik tersebut.\n\nBandingkan dengan duwagey di Mindanao, contoh instrumen gesek yang juga memiliki badan resonator. Persamaan prinsip membantu kita membaca organologi, sementara tradisi setiap komunitas tetap mempunyai sejarahnya sendiri. Pertanyaan perjalananmu: apa yang berubah ketika dawai digesek terus-menerus, dibandingkan ketika dawai dipetik lalu dibiarkan mereda?","narrativeEn":"A bowed string instrument associated with Sinrilik Pakesok-kesok storytelling. Explore the relationship between bow, strings and resonator.","development":"Kronologi perkembangan bentuk belum terverifikasi.","developmentEn":"A verified chronology of changes to the form is not yet available.","video":"assets/videos/gesok-gesok.webm","videoKind":"schematic","modelType":"gesok-gesok","modelUrl":"","diagram":"assets/exploded/gesok-gesok.svg","diagramEn":"assets/exploded/gesok-gesok-en.svg","gallery":[],"parts":[{"title":"Dawai","description":"Getaran dipertahankan melalui gesekan.","titleEn":"Strings","descriptionEn":"Vibrate through friction from the bow.","position":null},{"title":"Leher","description":"Penopang dawai pada skema.","titleEn":"Neck","descriptionEn":"Supports the strings in the model.","position":null},{"title":"Resonator","description":"Badan sederhana yang meneruskan getaran.","titleEn":"Resonator","descriptionEn":"Helps make string vibrations audible.","position":null},{"title":"Busur","description":"Bagian penggesek; bahan dan ukuran belum diukur.","titleEn":"Bow","descriptionEn":"Friction sustains string vibration.","position":null}],"sources":[{"title":"Kemendikbud — Warisan Budaya Takbenda 2013, buku dua","url":"https://repositori.kemendikdasmen.go.id/23499/1/Warisan%20budaya%20tak%20benda%20Indonesia%20penetapan%20tahun%202013%20buku%20dua.pdf"},{"title":"NCCA Filipina — Philippine Music Instruments","url":"https://ncca.gov.ph/about-ncca-3/subcommissions/subcommission-on-the-arts-sca/music/philippine-music-instruments/"}],"published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('alosu','{"id":"alosu","name":"ALOSU","category":"idiofon","region":"bone soppeng","technique":"digoyangkan","keywords":"alosu bissu maggiri getar bambu","description":"Instrumen goyang pada metadata prototipe Bone–Soppeng. Amati hubungan gerak, wadah, dan getaran dalam keluarga idiofon.","subtitle":"Idiofon · Getar Bambu Berbiji Sakral","image":"assets/alosu.jpg","audio":null,"descriptionEn":"A shaken instrument listed for Bone–Soppeng in the prototype. Explore how movement, a container and its contents create vibration.","narrative":"Alosu menjadi titik awal untuk mendengar tubuh instrumen itu sendiri. Ketika sebuah wadah berisi partikel digerakkan, benturan di dalamnya dapat menghasilkan bunyi berulang. Pada skema ini, isi ditampilkan sebagai butiran konseptual agar hubungan gerak, benturan, dan wadah terlihat. Bahan serta susunan isi artefak sebenarnya perlu diperiksa melalui dokumentasi.\n\nMetadata rancangan awal menghubungkan Alosu dengan wilayah Bone dan Soppeng serta konteks Bissu. Untuk prototipe, titik ini mengajak pengunjung berhenti sejenak: sebuah benda bunyi dapat mempunyai kedudukan sosial yang tidak terlihat hanya dari bentuk luarnya. Kisah penggunaan, istilah lokal, dan batas dokumentasinya perlu dirumuskan bersama pemilik pengetahuan budaya.\n\nDalam keluarga idiofon, bandingkan prinsip Alosu dengan Angklung: keduanya dapat digerakkan, tetapi bagian yang berbenturan dan bentuk resonansinya berbeda. Kemiripan gerak bukan berarti kesamaan fungsi budaya. Pertanyaan perjalananmu: bagian mana yang benar-benar menghasilkan getaran, dan apa yang perlu kita tanyakan kepada komunitas sebelum menafsirkan bunyinya?","narrativeEn":"A shaken instrument listed for Bone–Soppeng in the prototype. Explore how movement, a container and its contents create vibration.","development":"Kronologi perkembangan bentuk belum terverifikasi.","developmentEn":"A verified chronology of changes to the form is not yet available.","video":"assets/videos/alosu.webm","videoKind":"schematic","modelType":"alosu","modelUrl":"","diagram":"assets/exploded/alosu.svg","diagramEn":"assets/exploded/alosu-en.svg","gallery":[],"parts":[{"title":"Penutup","description":"Menahan isi dalam skema wadah.","titleEn":"Lid","descriptionEn":"Closes the conceptual container.","position":null},{"title":"Isi konseptual","description":"Butiran yang membentur bagian dalam.","titleEn":"Contents","descriptionEn":"Move and strike the container when shaken.","position":null},{"title":"Wadah","description":"Badan instrumen pada skema.","titleEn":"Container","descriptionEn":"The body helps shape the sound.","position":null},{"title":"Pegangan","description":"Tempat gerak tangan diteruskan ke wadah.","titleEn":"Handle","descriptionEn":"Supports the shaking movement.","position":null}],"sources":[{"title":"Smithsonian — keluarga instrumen berdawai","url":"https://festival.si.edu/articles/1975/the-world-family-of-stringed-instruments"},{"title":"UNESCO — Indonesian Angklung","url":"https://ich.unesco.org/en/RL/indonesian-angklung-00393"}],"published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('popondi','{"id":"popondi","name":"POPONDI / TOLINDO","category":"kordofon","region":"toraja luwu","technique":"dipetik","keywords":"popondi tolindo satu dawai tempurung","description":"Instrumen petik satu dawai pada metadata prototipe Toraja–Luwu. Eksplorasi penopang dawai dan resonator konseptual.","subtitle":"Kordofon · Satu Dawai Tempurung Kelapa","image":"assets/popondi.jpg","audio":null,"descriptionEn":"A single-string plucked instrument listed for Toraja–Luwu in the prototype. Explore the string support and conceptual resonator.","narrative":"Popondi atau Tolindo menutup rangkaian petikan dengan fokus pada satu dawai dalam metadata prototipe. Jumlah dawai yang sedikit tidak membuat pengalaman bunyinya sederhana. Gerak pemain, tegangan, dan resonator tetap membentuk kemungkinan ekspresi. Pada model ini, lengkungan penopang dan badan resonansi ditampilkan secara abstrak agar jalur getaran mudah dibaca.\n\nRancangan awal menempatkan instrumen ini pada konteks Toraja dan Luwu serta suasana perayaan panen. Narasi tersebut dipertahankan sebagai arah cerita prototipe, bukan sebagai penetapan persebaran atau sejarah final. Bayangkan ruang berkumpul tempat bunyi, percakapan, dan rasa syukur saling hadir; dokumentasi masyarakat setempat diperlukan untuk mengisi kisah ini dengan suara yang tepat.\n\nBandingkan prinsip resonator dan dawai dengan contoh lain dalam keluarga kordofon. Kemudian kembali ke Kacaping dan Gesok-gesok untuk melihat perbedaan petikan serta gesekan. Pertanyaan perjalananmu: jika hanya satu dawai digunakan, bagaimana gerak pemain dan bentuk badan dapat membuka ragam pengalaman mendengar?","narrativeEn":"A single-string plucked instrument listed for Toraja–Luwu in the prototype. Explore the string support and conceptual resonator.","development":"Kronologi perkembangan bentuk belum terverifikasi.","developmentEn":"A verified chronology of changes to the form is not yet available.","video":"assets/videos/popondi.webm","videoKind":"schematic","modelType":"popondi","modelUrl":"","diagram":"assets/exploded/popondi.svg","diagramEn":"assets/exploded/popondi-en.svg","gallery":[],"parts":[{"title":"Dawai","description":"Sumber getaran melalui petikan.","titleEn":"String","descriptionEn":"The source of vibration when plucked.","position":null},{"title":"Penopang lengkung","description":"Struktur penegang dawai konseptual.","titleEn":"Support","descriptionEn":"Holds the string along its length.","position":null},{"title":"Resonator","description":"Badan berbentuk mangkuk dalam skema.","titleEn":"Resonator","descriptionEn":"A shell-shaped cavity in this conceptual model.","position":null},{"title":"Penghubung","description":"Jalur getaran menuju resonator.","titleEn":"Bridge","descriptionEn":"Connects string vibration to the resonator.","position":null}],"sources":[{"title":"Smithsonian — keluarga instrumen berdawai","url":"https://festival.si.edu/articles/1975/the-world-family-of-stringed-instruments"},{"title":"NCCA Filipina — Philippine Music Instruments","url":"https://ncca.gov.ph/about-ncca-3/subcommissions/subcommission-on-the-arts-sca/music/philippine-music-instruments/"}],"published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('gong','{"id":"gong","name":"GONG","category":"idiofon","region":"makassar sulawesi selatan","technique":"dipukul","description":"Gong berbunyi melalui getaran badan logam yang dipukul. Instrumen ini disebut bersama gandrang dan puik-puik dalam dokumentasi permainan Gandrang Makassar.","descriptionEn":"A gong sounds through the vibration of its struck metal body. It is documented alongside gandrang and puik-puik in Makassar Gandrang performance.","modelType":"gong","sources":[{"title":"BPNB Sulawesi Selatan — Ragam Teknik Memainkan Gandrang","url":"https://kebudayaan.kemdikbud.go.id/bpnbsulsel/ragam-teknik-memainkan-gandrang/"}],"parts":[{"title":"Pencu","description":"Bagian pusat yang menonjol dalam skema.","titleEn":"Boss","descriptionEn":"The raised centre in this conceptual model.","position":[0,0,0.5]},{"title":"Badan logam","description":"Permukaan logam menjadi sumber getaran.","titleEn":"Metal body","descriptionEn":"The metal surface is the vibrating body.","position":[0.8,0.5,0.1]},{"title":"Bibir","description":"Tepi melengkung pada model konseptual.","titleEn":"Rim","descriptionEn":"The curved edge in the conceptual model.","position":[-1.4,0,0]},{"title":"Penggantung","description":"Penopang gong; bahan dan ukuran perlu dokumentasi.","titleEn":"Suspension","descriptionEn":"Supports the gong; materials and dimensions need documentation.","position":[0.6,1.9,0]}],"image":"assets/illustrations/gong.svg","imageKind":"schematic","narrative":"Gong berbunyi melalui getaran badan logam yang dipukul. Instrumen ini disebut bersama gandrang dan puik-puik dalam dokumentasi permainan Gandrang Makassar.","narrativeEn":"A gong sounds through the vibration of its struck metal body. It is documented alongside gandrang and puik-puik in Makassar Gandrang performance.","audio":null,"video":null,"videoKind":"schematic","modelUrl":"","diagram":"","diagramEn":"","gallery":[],"development":"Kronologi perubahan bentuk belum terverifikasi. Model dan ilustrasi bukan dokumentasi artefak terukur.","developmentEn":"A chronology of changes is not yet verified. The model and illustration are not measured artefact documentation.","published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('suling-lembang','{"id":"suling-lembang","name":"SULING LEMBANG","category":"aerofon","region":"toraja sulawesi selatan","technique":"ditiup","description":"Instrumen tiup bambu dari Toraja. Telusuri hubungan napas, saluran udara, dan bukaan nada melalui skema edukatif; bentuk dan ukuran artefak perlu dokumentasi.","descriptionEn":"A bamboo wind instrument from Toraja. Explore breath, the air channel and finger openings through an educational model; artefact shape and measurements require documentation.","modelType":"flute","sources":[{"title":"Universitas Negeri Makassar — Suling Lembang dalam upacara Mangrara","url":"https://eprints.unm.ac.id/16744/1/SKRIPSI%20BERNA%20TODING.pdf"}],"parts":[{"title":"Bagian tiup","description":"Tempat napas diarahkan ke instrumen pada skema.","titleEn":"Blowing end","descriptionEn":"Where breath is directed into the conceptual instrument.","position":null},{"title":"Tabung bambu","description":"Saluran udara pada model.","titleEn":"Bamboo tube","descriptionEn":"The air channel in the model.","position":null},{"title":"Lubang nada","description":"Bukaan nada ditampilkan secara sederhana.","titleEn":"Finger holes","descriptionEn":"Simplified pitch openings.","position":null},{"title":"Ujung tabung","description":"Bagian akhir saluran udara dalam skema.","titleEn":"Tube end","descriptionEn":"The end of the conceptual air channel.","position":null}],"image":"assets/illustrations/suling-lembang.svg","imageKind":"schematic","narrative":"Instrumen tiup bambu dari Toraja. Telusuri hubungan napas, saluran udara, dan bukaan nada melalui skema edukatif; bentuk dan ukuran artefak perlu dokumentasi.","narrativeEn":"A bamboo wind instrument from Toraja. Explore breath, the air channel and finger openings through an educational model; artefact shape and measurements require documentation.","audio":null,"video":null,"videoKind":"schematic","modelUrl":"","diagram":"","diagramEn":"","gallery":[],"development":"Kronologi perubahan bentuk belum terverifikasi. Model dan ilustrasi bukan dokumentasi artefak terukur.","developmentEn":"A chronology of changes is not yet verified. The model and illustration are not measured artefact documentation.","published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_instruments(id,content) values ('rebana','{"id":"rebana","name":"REBANA","category":"membranofon","region":"sulawesi selatan","technique":"ditepuk","description":"Instrumen selaput dengan bingkai. Rebana tercatat dalam katalog koleksi Museum La Galigo; identitas pembuat, penggunaan lokal, dan rincian artefak perlu dilengkapi kurator.","descriptionEn":"A membrane instrument with a frame. Rebana appears in the La Galigo Museum collection catalogue; maker, local usage and artefact details remain to be supplied by the curator.","modelType":"frame-drum","sources":[{"title":"Museum La Galigo — Koleksi Pilihan Jilid 1","url":"https://repositori.kemendikdasmen.go.id/29894/1/KOLEKSI%20PILIHAN%20MUSEUM%20NEGERI%20PROPINSI%20SULSEL%20LA%20GALIGO%20JILID%201.pdf"}],"parts":[{"title":"Selaput","description":"Permukaan sumber getaran ketika ditepuk.","titleEn":"Membrane","descriptionEn":"The surface vibrates when struck.","position":null},{"title":"Bingkai","description":"Penopang selaput pada model.","titleEn":"Frame","descriptionEn":"Supports the membrane in the model.","position":null},{"title":"Tepi pengikat","description":"Hubungan selaput dan bingkai secara konseptual.","titleEn":"Attachment edge","descriptionEn":"The conceptual connection between membrane and frame.","position":null},{"title":"Ruang belakang","description":"Sisi terbuka pada skema rebana.","titleEn":"Open back","descriptionEn":"The open side of the conceptual frame drum.","position":null}],"image":"assets/illustrations/rebana.svg","imageKind":"schematic","narrative":"Instrumen selaput dengan bingkai. Rebana tercatat dalam katalog koleksi Museum La Galigo; identitas pembuat, penggunaan lokal, dan rincian artefak perlu dilengkapi kurator.","narrativeEn":"A membrane instrument with a frame. Rebana appears in the La Galigo Museum collection catalogue; maker, local usage and artefact details remain to be supplied by the curator.","audio":null,"video":null,"videoKind":"schematic","modelUrl":"","diagram":"","diagramEn":"","gallery":[],"development":"Kronologi perubahan bentuk belum terverifikasi. Model dan ilustrasi bukan dokumentasi artefak terukur.","developmentEn":"A chronology of changes is not yet verified. The model and illustration are not measured artefact documentation.","published":true}'::jsonb) on conflict(id) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('4d1d2e9a75426ae3099813ad2a399cd18b1aa31ea29c1a8e118cc0f4b8449068','Instrumen tabuh dalam tradisi musik Makassar. Telusuri hubungan selaput, badan resonansi, dan irama dalam konteks pertunjukan.','A drum in Makassar musical traditions. Explore how membranes, a hollow body and the player’s touch shape rhythm.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('4c1238cac902fc5f681ff9c667ab86366920628e1fd3a513badad2d431f67dbe','Mulailah dengan memperhatikan badan Gandrang dan permukaan tabuhnya. Dalam keluarga membranofon, selaput yang dibentangkan menjadi sumber getaran utama. Rongga badan membantu membentuk resonansi, sementara sentuhan pemain memberi tekanan, jeda, dan aksen. Di titik ini, kita mengajak pengunjung membaca irama sebagai rangkaian keputusan, bukan sekadar deretan pukulan.
insert into public.rerasa_translations(hash,source,translated) values('a16fa243fd0cf6263ca4e62c15e9482f9ec36e787f7a473b25247b82f8e18fd0','Kronologi perkembangan bentuk belum terverifikasi.','A verified chronology of changes to the form is not yet available.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('f22cb6c7ac3e730e9e84e0e5bcd8191a406c55832025aa8d6f354f8467ebb5cd','Selaput atas','Upper membrane') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('b928e49c6b583012738ccb7fd1b29290fa9fa75c14fb1e7d3ce845afe760bd81','Permukaan yang bergetar saat ditabuh.','The surface vibrates when struck.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('544ab8ba0a0b33e245f7f6be6d698aba08bad80b994b99bf0f51b3fd0c2d56f5','Badan berongga','Hollow body') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('025d5cb5c28d8ac16cb22584561873c650a115b3dec43fa284db3243cc7ffaf4','Ruang yang membantu membentuk resonansi.','The cavity helps shape resonance.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('3a3854511e21f04e666e9f13e4a94d214b8ece9994f11a9e2c27f7d8fb9823b2','Pengikat','Tension cords') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('d00c790b8d406d2927870abea1db49477ed66b6dff5c861eecc5027e094fde1d','Menahan dan mengatur tegangan selaput dalam skema.','Hold the membranes and regulate their tension in this model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('bf3366af5373455f4ff19d339e1446ad1eb91032c55cc7a1b1c54f87fe82fd67','Selaput bawah','Lower membrane') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('bdca1020b465a3f6b920b23a20de3e83884dfd3f734ab9b13dc3f14a9938e2ae','Permukaan kedua pada model konseptual.','A second vibrating surface in this conceptual model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('3363cfbf00c8c6e8daaf35981d5388bd24d0567e244101b4efb71dc1dd0b252d','Instrumen petik dalam kebudayaan Mandar, Bugis, dan Makassar. Petikan dawai dan syair membuka ruang untuk cerita.','A plucked string instrument in Mandar, Bugis and Makassar cultures. Strings and poetry open a space for storytelling.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('c1e078b1b665c0502f7dc1eea7be4d04611fea70cf04a477ca104b05626dd780','Di hadapan Kacaping, perhatian berpindah dari pukulan menuju petikan. Dawai yang ditarik lalu dilepaskan bergetar, dan getaran itu diteruskan ke badan instrumen. Perhatikan jalur pendek antara ujung jari, dawai, dan ruang resonansi. Pada model konseptual ini, bentuk memanjang digunakan untuk membantu melihat hubungan antarbagiannya, bukan untuk menggantikan pengukuran artefak.
insert into public.rerasa_translations(hash,source,translated) values('b980342c3520a130d4e3b4bdd9abe014b773eef20ce6d4e2049ac78183aa786e','Dawai','String') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('8a56c19bbdf7aa2dd02b316a496f38c88dd55d3590ff5b0051373ed6db10a30b','Sumber getaran ketika dipetik.','The source of vibration when plucked.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('354306e765ef2703395be9f2730de5e3aa23a04f1c2f31dabf10930b1fa47fcd','Jembatan dawai','Bridge') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('f6ff00c685ef891bc3bd23f83220922f5bdafe4de224529e16235b5e80485b88','Meneruskan getaran ke badan dalam skema.','Transfers string vibration to the body.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('61c4dcbf006808cbe1adb3b8a8008b0679ed9b79db4125d94289a99d75d52e01','Papan permukaan','Soundboard') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('6306eb1950af7ee5e9bb93aea0b08f76ebb3b940708004888e3616bf9b42f87f','Permukaan resonator konseptual.','The surface of the conceptual resonator.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('59f8f7cf7658db5c66c90672cf4bea9b158651f762fcf7dda6f0ad35d8aa1c62','Badan kayu','Wooden body') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('610c8b8e809798350d45452d4a659a48db8ef54190b3093ecfdc792b3546135a','Rongga untuk memperjelas hubungan bentuk dan bunyi.','A cavity that illustrates the relationship between shape and sound.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('c74275a87f72204daf0abd43c6394ecdb7b478995253edf3c1ac88f93c1306a3','Instrumen tiup pada metadata prototipe Makassar–Gowa. Telusuri hubungan napas, saluran udara, dan karakter bunyi.','A wind instrument associated with Makassar–Gowa in the prototype metadata. Follow breath through the mouthpiece, air channel and bell.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('e248c23de142a58db6ccefc0dd70f86f6a6906b1d3bbf752074910fa9b695ee3','Jalur aerofon dimulai dengan napas. Pada Pui-pui, pengunjung diajak membayangkan udara memasuki bagian peniup, bergerak melewati badan, lalu keluar melalui ujung instrumen. Visualisasi ini menyederhanakan bagian-bagian tersebut agar hubungan antara napas, saluran, dan keluaran bunyi dapat dipahami. Detail bentuk lidah dan ukurannya masih memerlukan dokumentasi langsung.
insert into public.rerasa_translations(hash,source,translated) values('e405b18851198bbb7726598b5d068f8535c05b7d3cf2663f7baef69cf07bc25e','Bagian peniup','Mouthpiece') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('3b4de532eff2d00abbaeddac804ad89615616663e4bfffc4915176963b5d1c0f','Tempat masuk napas; bentuk lidah disederhanakan.','Air enters here; the reed shape is simplified.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('861db7c97cc321f24e3a979934c5ee995e83d02151c8aef45a8397a53f6a736b','Badan saluran','Bore') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('16c2a9679b5629d46fd65098a6ea910cbd657c1a3de2c8498b90b98ac0e37246','Ruang aliran udara pada model.','The air passage within the model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('effb3f0c1dfaeaef1a44068fe5330f844174b8cf270bc8b2e3f5f323ebd64a3f','Lubang nada','Finger holes') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('01197ed6f766c278581af4c909d333d8324aa669c4e3dba1b28c65a451b3640d','Bukaan yang ditampilkan secara konseptual.','Conceptual openings used to explore pitch.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('31cc86f5e984f0e1c4fd80a0a329a5236994274a89e9a49d7d7bbd8400e1d12b','Corong ujung','Bell') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('ec3bc4a014d0b560fcff474d5060ee189e8579f70c946034771d96a614b509e4','Bagian keluaran pada model prototipe.','The outlet of the prototype model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('06f3fc4c9298d9b2a7a7e8b0c2bd745b5b79776d54c8a398d63ba180c2fc53dc','Instrumen gesek yang berkaitan dengan Sinrilik Pakesok-kesok. Gerak busur mempertemukan getaran dawai dengan penuturan cerita.','A bowed string instrument associated with Sinrilik Pakesok-kesok storytelling. Explore the relationship between bow, strings and resonator.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('8523428708f6ef6e6ba20d6121b21d6efd9c80b4d94ef2091e6ba83450895303','Gesok-gesok memberi pengalaman berbeda di jalur kordofon. Jika petikan menghasilkan getaran setelah dawai dilepaskan, gesekan dapat mempertahankan getaran selama busur bergerak. Perhatikan posisi dawai, badan resonator, dan busurnya. Ketiganya membentuk hubungan gerak yang dapat dieksplorasi melalui model sederhana pada layar.
insert into public.rerasa_translations(hash,source,translated) values('bcc34b10126286c34a512757519841e37a1a56306e47c07072c362e3b17a6a76','Getaran dipertahankan melalui gesekan.','Vibrate through friction from the bow.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('d2cfc7e75f1d4864de04e3cf1be601b6057b901c360813b0823c80f0c42283b3','Leher','Neck') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('b53563f4dcc937b9d21b97a9f0c7396fd7f3887ee6f5f691a1ebbb546be12176','Penopang dawai pada skema.','Supports the strings in the model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('cd3bb166aa90f89c24472c69096fb8a589f65324c1abc035c82cab7d57ed2e73','Resonator','Resonator') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('767223187d6be6ed396cdacec37f3ae9302c5687c7680fd67e16ff404c41c362','Badan sederhana yang meneruskan getaran.','Helps make string vibrations audible.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('7112a70df5d83c8e8fede0982087f5adb548393a71922ef3f159a72c075eabf9','Busur','Bow') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('14b5a5c0768dd11f09dbc5d3f11bca03b11a59d0d3856db6493457beacaaff6f','Bagian penggesek; bahan dan ukuran belum diukur.','Friction sustains string vibration.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('c01dcd1c2d83bc3928b355a50dcc5b1b5d49ba5d3ec83bab496ba0cacd0927f1','Instrumen goyang pada metadata prototipe Bone–Soppeng. Amati hubungan gerak, wadah, dan getaran dalam keluarga idiofon.','A shaken instrument listed for Bone–Soppeng in the prototype. Explore how movement, a container and its contents create vibration.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('9958814e37c8c5aad58da794d2834728e37bce963c5d11138efdc8fbb7e00689','Alosu menjadi titik awal untuk mendengar tubuh instrumen itu sendiri. Ketika sebuah wadah berisi partikel digerakkan, benturan di dalamnya dapat menghasilkan bunyi berulang. Pada skema ini, isi ditampilkan sebagai butiran konseptual agar hubungan gerak, benturan, dan wadah terlihat. Bahan serta susunan isi artefak sebenarnya perlu diperiksa melalui dokumentasi.
insert into public.rerasa_translations(hash,source,translated) values('e2e53ab72a66a1567fed2b77d639f271a2c50a6ecaf36724d32e752b8b9c808f','Penutup','Lid') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('f50539b815685abb36cd7e16dbaaae3584db92c007659bb8e580ef0c71443fc8','Menahan isi dalam skema wadah.','Closes the conceptual container.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('d32bd467543b1e6b8bf0417c88a9ec638b9380e8dd4d529ff0e8497e2ddb3b14','Isi konseptual','Contents') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('52bb23a969a9ed2d1bcff5348275f48fa43ec30c0c9d2a63af81c8aeff79c4d3','Butiran yang membentur bagian dalam.','Move and strike the container when shaken.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('d1fa6d1e15c06091003d8d33940d1ae2c6c4e70e7c91771ac553ecbd173aee1e','Wadah','Container') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('7567beda1811b03dbb16050c68da70a1c5ebc15e7ef335402b7dad22075246d1','Badan instrumen pada skema.','The body helps shape the sound.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('84c00c4886266bc2d8ee65548d22da41478e259188fbfb22ca2fea1ade359275','Pegangan','Handle') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('9e9e5f85cc729487da0782b96d51ce4c0487b38b4c9f4f9ef3ad609327d6ba0b','Tempat gerak tangan diteruskan ke wadah.','Supports the shaking movement.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('3838de8dfed0b624d3986fd68c174b540ba9ba242346b270516f693db48a200b','Instrumen petik satu dawai pada metadata prototipe Toraja–Luwu. Eksplorasi penopang dawai dan resonator konseptual.','A single-string plucked instrument listed for Toraja–Luwu in the prototype. Explore the string support and conceptual resonator.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('304e6cac25ccb6bfcfc1d26c9162f0b6d0256a941e256fa185d86b26670275e5','Popondi atau Tolindo menutup rangkaian petikan dengan fokus pada satu dawai dalam metadata prototipe. Jumlah dawai yang sedikit tidak membuat pengalaman bunyinya sederhana. Gerak pemain, tegangan, dan resonator tetap membentuk kemungkinan ekspresi. Pada model ini, lengkungan penopang dan badan resonansi ditampilkan secara abstrak agar jalur getaran mudah dibaca.
insert into public.rerasa_translations(hash,source,translated) values('59f85620f82cbea15004a71d680d6479660b008813992b92c0cab0d86ef410e5','Sumber getaran melalui petikan.','The source of vibration when plucked.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('a23f1d35804121b175b4b9f5edef26cfd7db8794c129375225bd18bd53b319bf','Penopang lengkung','Support') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('687779831b086a8de01c06669dc12077fa4d7f33bb7df7c44dc0c3ab0d7b17f5','Struktur penegang dawai konseptual.','Holds the string along its length.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('27862a0837a5633281af24a34dc77d94ee694bd8efe0e4dd2e8fa675ab205247','Badan berbentuk mangkuk dalam skema.','A shell-shaped cavity in this conceptual model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('49da85b9063b776e237de571f33ee97e2fbbff88efb32317b1eca9cc7aa5aff9','Penghubung','Bridge') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('948e4e7a2f5ac76d7cd882aeaeeba779fc4b0fd3e26f080217fc06018bb2c28e','Jalur getaran menuju resonator.','Connects string vibration to the resonator.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('101076196adbce1b301bc9e4d9a8d6ea666a8993463fabba6dd55a88deff854b','Gong berbunyi melalui getaran badan logam yang dipukul. Instrumen ini disebut bersama gandrang dan puik-puik dalam dokumentasi permainan Gandrang Makassar.','A gong sounds through the vibration of its struck metal body. It is documented alongside gandrang and puik-puik in Makassar Gandrang performance.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('8a5e7dd5e661a17880218a2b5288c370bf5fe1c55f10ddd8b455c08facd1ffdd','Kronologi perubahan bentuk belum terverifikasi. Model dan ilustrasi bukan dokumentasi artefak terukur.','A chronology of changes is not yet verified. The model and illustration are not measured artefact documentation.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('a5515f896fb8bde2785011b85646e3c27379b9ce8b8b1df25a2bf649b0089de1','Pencu','Boss') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('2f6028702abcd6a48e99d7e9d338816fabcae04734147da9e79907a4f10144dc','Bagian pusat yang menonjol dalam skema.','The raised centre in this conceptual model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('bd7385409322baedbfad5043f332f36b507c56f33ea5010c37f41d1e5a116e5d','Badan logam','Metal body') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('eb240dd7b50f0a33b16410a1c3e1c519dd2bfa5111aca410766d4a05f5a3e784','Permukaan logam menjadi sumber getaran.','The metal surface is the vibrating body.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('bb14322f1af7a059d4972037b243077bd0964f7ae27817249e06344657e02496','Bibir','Rim') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('4246826cad21e6b015caf0c7f9d073a28678ed997f713e1b912edd6ecbd9f731','Tepi melengkung pada model konseptual.','The curved edge in the conceptual model.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('c3ff11c8b4b3767e3714a35f616766dd7ea258fbe03467eb4d9a31f19fd62d81','Penggantung','Suspension') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('8414736a7f4f88c137bdb7f092d97ad58c749c5a1949253af204cf8155780d42','Penopang gong; bahan dan ukuran perlu dokumentasi.','Supports the gong; materials and dimensions need documentation.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('46d7cb655e2ffa3f3a664bd7a5778251cfd24c48e391628b8bfa8b45f8eb9abe','Instrumen tiup bambu dari Toraja. Telusuri hubungan napas, saluran udara, dan bukaan nada melalui skema edukatif; bentuk dan ukuran artefak perlu dokumentasi.','A bamboo wind instrument from Toraja. Explore breath, the air channel and finger openings through an educational model; artefact shape and measurements require documentation.') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('9cb4e3a26ab0bd9cd5ed3085db3426410d65e691b57cd58b0c505df07da7c4ac','Bagian tiup','Blowing end') on conflict(hash) do nothing;
insert into public.rerasa_translations(hash,source,translated) values('14600f158b5f4d3c8e976b1cc7c5007cb89e7922c3ff11904365548dd5530159','Tempat napas diarahkan ke instrumen pada skema.','Where breath is directed into the conceptual instrument.') on conflict(hash) do nothing;
